package com.coreauth.validator;
import com.coreauth.validator.canonical.ProprietaryDataLoadPayloadValidator;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.databind.node.ObjectNode;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class ProprietaryDataLoadPayloadValidatorTest{static final ObjectMapper M=new ObjectMapper();@Test void request(){assertThat(new ProprietaryDataLoadPayloadValidator().validatePayload(req()).errors()).isEmpty();}@Test void response(){assertThat(new ProprietaryDataLoadPayloadValidator().validatePayload(resp()).errors()).isEmpty();}@Test void rejectsSegment100(){ObjectNode p=req();((ObjectNode)p.path(ProprietaryDataLoadPayloadValidator.REQUEST_ROOT)).putObject("Standard Message Data Segment");assertRule(p,"PDL-REQ-003");}@Test void rejectsWrongDirection(){ObjectNode p=req();((ObjectNode)p.path(ProprietaryDataLoadPayloadValidator.REQUEST_ROOT).path("Proprietary Data Load Segment")).put("PromptCode","901");assertRule(p,"PDL-REQ-004");}static void assertRule(ObjectNode p,String id){assertThat(new ProprietaryDataLoadPayloadValidator().validatePayload(p).errors()).anyMatch(e->e.reason().contains(id));}static ObjectNode req(){ObjectNode p=M.createObjectNode(),n=p.putObject(ProprietaryDataLoadPayloadValidator.REQUEST_ROOT);n.put("MessageType","ATL105");n.put("NumSegments","1");ObjectNode s=n.putObject("Proprietary Data Load Segment");s.put("SegmentType","118");s.put("PromptCode","903");return p;}static ObjectNode resp(){ObjectNode p=M.createObjectNode(),n=p.putObject(ProprietaryDataLoadPayloadValidator.RESPONSE_ROOT);n.put("ResponseCode","T");n.put("DownloadIndicator","0");n.put("InitiationDate","260930");n.put("InitiationTime","1530");n.put("SequenceNumber","000001");n.putObject("Proprietary Data Load Segment").put("PromptCode","902");return p;}}
